<script>
(function(){
  'use strict';

  /* ---------- Filesystem data ---------- */
  const FS = {
    '/': ['bin','boot','dev','etc','home','lib','opt','root','tmp','usr','var'],
    '/bin': ['bash','cat','ls','cp','mv','rm'],
    '/etc': ['hosts','hostname','passwd','resolv.conf','fstab','apt','nginx'],
    '/etc/apt': ['sources.list'],
    '/etc/nginx': ['nginx.conf'],
    '/home': ['user'],
    '/home/user': ['Documents','Downloads','Pictures','Music','Desktop','.bashrc','.profile','notes.txt'],
    '/home/user/Documents': ['resume.pdf','todo.txt','budget.ods','project'],
    '/home/user/Documents/project': ['main.js','README.md'],
    '/home/user/Downloads': ['ubuntu-22.04.iso','installer.deb','archive.tar.gz'],
    '/home/user/Pictures': ['wallpaper.png','photo.jpg','screenshot.png','vacation'],
    '/home/user/Pictures/vacation': ['beach.jpg','mountain.jpg','sunset.jpg'],
    '/home/user/Music': ['song1.mp3','playlist.m3u'],
    '/home/user/Desktop': ['shortcut.desktop'],
    '/usr': ['bin','lib','share','local'],
    '/usr/bin': ['python3','git','node','make'],
    '/usr/lib': ['libc.so','libssl.so'],
    '/usr/share': ['doc','man','icons'],
    '/usr/local': ['bin'],
    '/var': ['log','cache','lib','tmp'],
    '/var/log': ['syslog','auth.log','kern.log'],
    '/var/cache': ['apt'],
    '/var/lib': ['dpkg'],
    '/root': ['.bashrc'],
    '/boot': ['vmlinuz','initrd.img'],
    '/dev': ['sda','null','zero'],
    '/lib': ['libc.so.6'],
    '/opt': []
  };

  function isFolder(path, name){
    const child = joinPath(path, name);
    return Object.prototype.hasOwnProperty.call(FS, child);
  }
  function joinPath(dir, name){
    if (dir === '/') return '/' + name;
    return dir + '/' + name;
  }
  function parentOf(path){
    if (path === '/') return '/';
    const idx = path.lastIndexOf('/');
    if (idx <= 0) return '/';
    return path.slice(0, idx);
  }
  function baseName(path){
    if (path === '/') return '/';
    return path.slice(path.lastIndexOf('/') + 1);
  }

  /* ---------- Files app ---------- */
  const filesWindow = document.getElementById('files-window');
  const filesPath = document.getElementById('files-path');
  const filesList = document.getElementById('files-list');
  let currentPath = '/';

  function renderFiles(path){
    currentPath = path;
    filesPath.textContent = path === '/' ? '/' : path;
    filesList.innerHTML = '';
    const entries = FS[path] || [];
    entries.sort((a,b) => {
      const af = isFolder(path,a), bf = isFolder(path,b);
      if (af !== bf) return af ? -1 : 1;
      return a.localeCompare(b);
    });
    for (const name of entries){
      const folder = isFolder(path, name);
      const item = document.createElement('div');
      item.className = 'fs-item ' + (folder ? 'folder' : 'file');
      item.textContent = name;
      const icon = document.createElement('div');
      icon.className = 'fs-icon';
      icon.textContent = folder ? '🗂️' : '📄';
      // Insert icon before text
      item.textContent = '';
      item.appendChild(icon);
      const label = document.createElement('span');
      label.textContent = name;
      item.appendChild(label);

      item.addEventListener('dblclick', () => {
        if (folder) renderFiles(joinPath(path, name));
      });
      item.addEventListener('click', () => {
        document.querySelectorAll('.fs-item.selected').forEach(s => s.classList.remove('selected'));
        item.classList.add('selected');
      });
      filesList.appendChild(item);
    }
  }

  document.getElementById('files-up').addEventListener('click', () => {
    renderFiles(parentOf(currentPath));
  });
  document.getElementById('files-home').addEventListener('click', () => {
    renderFiles('/home/user');
  });

  /* ---------- Notepad app (persistent tabs) ---------- */
  const notepadWindow = document.getElementById('notepad-window');
  const tabsContainer = document.getElementById('tabs');
  const editor = document.getElementById('editor');
  const newTabBtn = document.getElementById('new-tab');

  const STORAGE_KEY = 'ubuntu-notepad-tabs-v1';
  let tabs = []; // [{id, name, content}]
  let activeId = null;

  function loadState(){
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw){
        const data = JSON.parse(raw);
        if (Array.isArray(data.tabs) && data.tabs.length){
          tabs = data.tabs.map(t => ({ id: t.id || genId(), name: t.name || 'Untitled', content: t.content || '' }));
          activeId = data.activeId && tabs.some(t => t.id === data.activeId) ? data.activeId : tabs[0].id;
          return;
        }
      }
    } catch(e){}
    // first run
    tabs = [{ id: genId(), name: 'Untitled 1', content: '' }];
    activeId = tabs[0].id;
  }
  function saveState(){
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ tabs, activeId }));
  }
  function genId(){ return 't' + Math.random().toString(36).slice(2,10); }

  function renderTabs(){
    tabsContainer.innerHTML = '';
    tabs.forEach(t => {
      const tab = document.createElement('div');
      tab.className = 'tab' + (t.id === activeId ? ' active' : '');
      tab.dataset.id = t.id;

      const name = document.createElement('span');
      name.className = 'tab-name';
      name.textContent = t.name;
      tab.appendChild(name);

      const close = document.createElement('button');
      close.className = 'tab-close';
      close.textContent = '×';
      close.title = 'Close tab';
      close.addEventListener('click', (e) => {
        e.stopPropagation();
        closeTab(t.id);
      });
      tab.appendChild(close);

      tab.addEventListener('click', () => activateTab(t.id));
      tabsContainer.appendChild(tab);
    });
    // New-tab button lives in strip
    const plus = document.createElement('button');
    plus.id = 'new-tab';
    plus.textContent = '+';
    plus.title = 'New tab';
    plus.addEventListener('click', newTab);
    tabsContainer.appendChild(plus);

    const active = tabs.find(t => t.id === activeId);
    editor.value = active ? active.content : '';
  }

  function activateTab(id){
    activeId = id;
    saveState();
    renderTabs();
  }
  function newTab(){
    const n = tabs.length + 1;
    const t = { id: genId(), name: 'Untitled ' + n, content: '' };
    tabs.push(t);
    activeId = t.id;
    saveState();
    renderTabs();
    editor.focus();
  }
  function closeTab(id){
    const idx = tabs.findIndex(t => t.id === id);
    if (idx === -1) return;
    tabs.splice(idx, 1);
    if (tabs.length === 0){
      tabs = [{ id: genId(), name: 'Untitled 1', content: '' }];
      activeId = tabs[0].id;
    } else if (activeId === id){
      activeId = tabs[Math.max(0, idx - 1)].id;
    }
    saveState();
    renderTabs();
  }

  let saveTimer = null;
  editor.addEventListener('input', () => {
    const active = tabs.find(t => t.id === activeId);
    if (active){
      active.content = editor.value;
      // Auto-rename Untitled tabs to first line if still default
      if (/^Untitled \d+$/.test(active.name)){
        const firstLine = editor.value.trim().split('\n')[0];
        if (firstLine){
          active.name = firstLine.slice(0, 24);
        }
      }
      clearTimeout(saveTimer);
      saveTimer = setTimeout(() => { saveState(); renderTabsKeepEditor(); }, 300);
      saveState();
    }
  });
  // Re-render tabs but keep focus & caret in editor
  function renderTabsKeepEditor(){
    const wasFocused = document.activeElement === editor;
    const start = editor.selectionStart, end = editor.selectionEnd;
    const val = editor.value;
    renderTabs();
    editor.value = val; // ensure value preserved
    if (wasFocused){
      editor.focus();
      try { editor.setSelectionRange(start, end); } catch(e){}
    }
  }

  /* ---------- Window management ---------- */
  function makeDraggable(win){
    const titlebar = win.querySelector('.titlebar');
    let drag = null;
    titlebar.addEventListener('mousedown', (e) => {
      if (e.target.closest('.controls button')) return;
      // Bring to front
      bringToFront(win);
      const rect = win.getBoundingClientRect();
      drag = { dx: e.clientX - rect.left, dy: e.clientY - rect.top };
      e.preventDefault();
    });
    document.addEventListener('mousemove', (e) => {
      if (!drag) return;
      let nx = e.clientX - drag.dx;
      let ny = e.clientY - drag.dy;
      const w = win.offsetWidth, h = win.offsetHeight;
      nx = Math.max(-w + 80, Math.min(window.innerWidth - 80, nx));
      ny = Math.max(28, Math.min(window.innerHeight - 40, ny));
      win.style.left = nx + 'px';
      win.style.top = ny + 'px';
    });
    document.addEventListener('mouseup', () => { drag = null; });
  }
  let zCounter = 10;
  function bringToFront(win){
    zCounter += 1;
    win.style.zIndex = zCounter;
  }

  function setupWindowControls(win){
    const close = win.querySelector('.win-close');
    close.addEventListener('click', () => { win.style.display = 'none'; });
    const min = win.querySelector('.win-min');
    min.addEventListener('click', () => { win.style.display = 'none'; });
    const max = win.querySelector('.win-max');
    let maximized = false, prev = null;
    max.addEventListener('click', () => {
      if (!maximized){
        prev = {
          left: win.style.left, top: win.style.top,
          width: win.style.width, height: win.style.height
        };
        win.style.left = '8px';
        win.style.top = '36px';
        win.style.width = (window.innerWidth - 16) + 'px';
        win.style.height = (window.innerHeight - 44 - 80) + 'px';
        maximized = true;
      } else {
        win.style.left = prev.left;
        win.style.top = prev.top;
        win.style.width = prev.width;
        win.style.height = prev.height;
        maximized = false;
      }
    });
    win.addEventListener('mousedown', () => bringToFront(win));
    makeDraggable(win);
  }

  setupWindowControls(filesWindow);
  setupWindowControls(notepadWindow);

  /* ---------- Launchers ---------- */
  document.getElementById('open-files').addEventListener('click', () => {
    filesWindow.style.display = 'flex';
    bringToFront(filesWindow);
    renderFiles(currentPath);
  });
  document.getElementById('open-notepad').addEventListener('click', () => {
    notepadWindow.style.display = 'flex';
    bringToFront(notepadWindow);
    renderTabs();
  });

  /* ---------- Clock ---------- */
  function updateClock(){
    const d = new Date();
    const hh = String(d.getHours()).padStart(2,'0');
    const mm = String(d.getMinutes()).padStart(2,'0');
    document.getElementById('clock').textContent = hh + ':' + mm;
  }
  updateClock();
  setInterval(updateClock, 1000 * 30);

  /* ---------- Init ---------- */
  loadState();
  // Pre-render files at root
  renderFiles('/');
  // Pre-render tabs (even though window hidden) so reopening shows them
  renderTabs();
})();
</script>
</body>
